from itertools import product

def is_valid_coloring(coloring):
    # Check all triangles for the invalid condition
    for i in range(N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                if len(set([coloring[i][j], coloring[j][k], coloring[k][i]])) == 2:
                    return False
    return True

# Number of vertices and colors
N = 4
M = 3

# Generate all possible colorings
for coloring in product(range(1, M+1), repeat=N*(N-1)//2):
    # Convert the flat list into a symmetric matrix
    matrix = [[0]*N for _ in range(N)]
    idx = 0
    for i in range(N):
        for j in range(i+1, N):
            matrix[i][j] = matrix[j][i] = coloring[idx]
            idx += 1

    if is_valid_coloring(matrix):
        break

# Convert the matrix to LaTeX format
latex_matrix = '\\begin{array}{' + 'c'*N + '}\n'
for row in matrix:
    latex_matrix += ' & '.join(map(str, row)) + ' \\\\\n'
latex_matrix += '\\end{array}'

print(latex_matrix)
